void answersABrokenRatePlanRuleWith400() throws Exception {
    HttpResponse<String> corporateWithoutCompany =
            post("/reservations", RESERVATION_JSON.replace("\"STANDARD\"", "\"CORPORATE\""));
    assertEquals(400, corporateWithoutCompany.statusCode());
    assertEquals("INVALID_REQUEST", json.readTree(corporateWithoutCompany.body()).get("error").asText());

    HttpResponse<String> weekendOnAMonday =
            post("/reservations", RESERVATION_JSON.replace("\"STANDARD\"", "\"WEEKEND_PACKAGE\""));
